describe('Payment Method Selection - PayPal', () => {
  beforeEach(() => {
    cy.visit('/checkout');
    cy.get('[data-testid="payment-section"]').should('be.visible');
  });

  it('should successfully select PayPal as payment method', () => {
    cy.get('[data-testid="payment-method-options"]').should('exist');

    cy.get('[data-testid="paypal-radio-button"]').should('be.visible').click();

    cy.get('[data-testid="paypal-radio-button"]').should('be.checked');

    cy.get('[data-testid="paypal-details-section"]').should('be.visible');

    cy.get('[data-testid="paypal-email-input"]').should('be.visible');

    cy.get('[data-testid="payment-method-confirmation"]').should('contain', 'PayPal');

    cy.get('[data-testid="continue-button"]').should('be.enabled');
  });

  it('should switch from credit card to PayPal payment method', () => {
    cy.get('[data-testid="credit-card-radio-button"]').click();
    cy.get('[data-testid="credit-card-radio-button"]').should('be.checked');

    cy.get('[data-testid="credit-card-details-section"]').should('be.visible');

    cy.get('[data-testid="paypal-radio-button"]').click();

    cy.get('[data-testid="paypal-radio-button"]').should('be.checked');
    cy.get('[data-testid="credit-card-radio-button"]').should('not.be.checked');

    cy.get('[data-testid="credit-card-details-section"]').should('not.be.visible');
    cy.get('[data-testid="paypal-details-section"]').should('be.visible');
  });

  it('should display PayPal payment form with required fields', () => {
    cy.get('[data-testid="paypal-radio-button"]').click();

    cy.get('[data-testid="paypal-email-input"]').should('be.visible').and('have.attr', 'required');
    cy.get('[data-testid="paypal-password-input"]').should('be.visible').and('have.attr', 'required');

    cy.get('[data-testid="paypal-email-input"]').type('user@example.com');
    cy.get('[data-testid="paypal-password-input"]').type('password123');

    cy.get('[data-testid="paypal-email-input"]').should('have.value', 'user@example.com');
    cy.get('[data-testid="paypal-password-input"]').should('have.value', 'password123');
  });

  it('should persist PayPal selection when navigating back and forth', () => {
    cy.get('[data-testid="paypal-radio-button"]').click();
    cy.get('[data-testid="paypal-radio-button"]').should('be.checked');

    cy.get('[data-testid="back-button"]').click();
    cy.get('[data-testid="forward-button"]').click();

    cy.get('[data-testid="paypal-radio-button"]').should('be.checked');
    cy.get('[data-testid="paypal-details-section"]').should('be.visible');
  });

  it('should show error when PayPal form is submitted with empty fields', () => {
    cy.get('[data-testid="paypal-radio-button"]').click();

    cy.get('[data-testid="continue-button"]').click();

    cy.get('[data-testid="paypal-email-error"]').should('be.visible').and('contain', 'Email is required');
    cy.get('[data-testid="paypal-password-error"]').should('be.visible').and('contain', 'Password is required');
  });

  it('should validate PayPal email format', () => {
    cy.get('[data-testid="paypal-radio-button"]').click();

    cy.get('[data-testid="paypal-email-input"]').type('invalid-email');
    cy.get('[data-testid="paypal-password-input"]').type('password123');

    cy.get('[data-testid="continue-button"]').click();

    cy.get('[data-testid="paypal-email-error"]').should('be.visible').and('contain', 'Invalid email format');
  });
});
